  /// Get unions for a given upazila name (supports Bengali, English, or normalized names).
  static List<String> getUnions(String upazila) {
    if (upazila.trim().isEmpty) return const [];
    final clean = upazila.trim();
    if (upazilaToUnions.containsKey(clean)) {
      return upazilaToUnions[clean]!;
    }
    final lower = clean.toLowerCase();
    if (upazilaToUnions.containsKey(lower)) {
      return upazilaToUnions[lower]!;
    }
    // Normalize by removing common suffixes/words
    final normalized = clean
        .replaceAll('উপজেলা', '')
        .replaceAll('সদর', '')
        .replaceAll('থানা', '')
        .replaceAll(RegExp(r'\b(sadar|upazila|thana)\b', caseSensitive: false), '')
        .trim();
    if (normalized.isNotEmpty) {
      if (upazilaToUnions.containsKey(normalized)) {
        return upazilaToUnions[normalized]!;
      }
      final normLower = normalized.toLowerCase();
      if (upazilaToUnions.containsKey(normLower)) {
        return upazilaToUnions[normLower]!;
      }
    }
    // Fuzzy substring match fallback
    for (var entry in upazilaToUnions.entries) {
      if (entry.key.length >= 3 && (entry.key.contains(clean) || clean.contains(entry.key))) {
        return entry.value;
      }
    }
    return const [];
  }
